#ifndef AGENDA_H
#define AGENDA_H

#define MAX 10
#define LARGO 20

typedef enum {
  OK,
  AGENDA_LLENA,
  NOMBRE_REPETIDO,
  NO_ENCONTRADO
} TResultado;

typedef struct {
  char nombres[MAX][LARGO];
  unsigned long telefonos[MAX];
  int cantidad;
} TAgenda;

void inicializar(TAgenda *a);
int total(TAgenda a);
TResultado agregar(TAgenda *a, char nombre[], unsigned long telefono);
TResultado buscar(TAgenda a, char nombre[], unsigned long *telefono);

#endif

