consignas.referencia:
#include <string.h>
#include "agenda.h"

void inicializar(TAgenda *a) {
  a->cantidad = 0;
}

int total(TAgenda a) {
  return a.cantidad;
}

TResultado agregar(TAgenda *a, char nombre[], unsigned long telefono) {
  for (int i = 0; i < a->cantidad; i++) {
    if (strcmp(a->nombres[i], nombre) == 0) {
      return NOMBRE_REPETIDO;
    }
  }
  if (a->cantidad == MAX) {
    return AGENDA_LLENA;
  }
  strcpy(a->nombres[a->cantidad], nombre);
  a->telefonos[a->cantidad] = telefono;
  a->cantidad = a->cantidad + 1;
  return OK;
}

TResultado buscar(TAgenda a, char nombre[], unsigned long *telefono) {
  for (int i = 0; i < a.cantidad; i++) {
    if (strcmp(a.nombres[i], nombre) == 0) {
      *telefono = a.telefonos[i];
      return OK;
    }
  }
  return NO_ENCONTRADO;
}

#include <stdio.h>
#include "agenda.h"

int main() {
  TAgenda a;
  char nombre[LARGO];
  unsigned long telefono;
  int n;
  int q;

  inicializar(&a);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%s", nombre);
    scanf("%lu", &telefono);
    agregar(&a, nombre, telefono);
  }
  printf("Contactos: %d\n", total(a));
  scanf("%d", &q);
  for (int i = 0; i < q; i++) {
    scanf("%s", nombre);
    if (buscar(a, nombre, &telefono) == OK) {
      printf("%lu\n", telefono);
    } else {
      printf("No esta\n");
    }
  }
  return 0;
}
